package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class EconomySupplyTest {
    private Properties settings(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/economy-demo.properties")),java.nio.charset.StandardCharsets.UTF_8)){var p=new Properties();p.load(r);return p;}catch(Exception e){throw new AssertionError(e);}}
    private final Properties p=settings();private final EconomyContent c=EconomyContent.parse(p);private final EconomyMerchants merchants=EconomyMerchants.parse(p,c);private final EconomyReport.Definition definition=EconomyReport.parse(p,c,merchants.first().shop());
    private EconomySupply.View view(Properties props,String good){var d=EconomyReport.parse(props,c,merchants.first().shop());return EconomySupply.project(c,d,merchants,EconomySupply.parse(props,c,d),EconomyEngine.initial(c),Map.of(),good);}
    @Test void oreSupplyContainsMarketsMineRecipeAndOneRoute(){var v=view(p,"iron_ore");assertEquals(2,v.nodes().stream().filter(n->n.section()==EconomySupply.Section.MARKET).count());assertEquals(1,v.nodes().stream().filter(n->n.section()==EconomySupply.Section.PRODUCER).count());assertEquals(1,v.nodes().stream().filter(n->n.section()==EconomySupply.Section.USE).count());assertEquals(1,v.nodes().stream().filter(n->n.section()==EconomySupply.Section.ROUTE).count());assertTrue(v.nodes().toString().contains("수도 시험 제련소"));}
    @Test void ingotHasNoUnrelatedOreRouteOrProducer(){var v=view(p,"iron_ingot");assertEquals(3,v.nodes().size());assertFalse(v.nodes().stream().anyMatch(n->n.section()==EconomySupply.Section.ROUTE));assertEquals(1,v.nodes().stream().filter(n->n.section()==EconomySupply.Section.PRODUCER).count());}
    @Test void guideUsesContentOrderAndRealPublicTargets(){var v=view(p,"iron_ore");assertEquals(4,v.steps().size());assertEquals("1. 광산 지역의 철광석 시장 확인",v.steps().getFirst().title());assertEquals("ore_road",v.steps().get(1).target().reference());assertEquals("capital_smelter",v.steps().get(2).target().reference());assertEquals("iron_ingot",v.steps().getLast().target().reference());assertTrue(v.steps().get(1).target().lines().stream().anyMatch(s->s.contains("개인 가방")));}
    @Test void absentGuideIsNotInvented(){var old=settings();old.remove("guide-steps");assertEquals(0,EconomySupply.parse(old,c,definition).size());assertTrue(view(old,"iron_ore").steps().isEmpty());assertEquals(c.fingerprint(),EconomyContent.parse(old).fingerprint());}
    @Test void hiddenRegionFacilityRouteAndMerchantDoNotLeak(){var limited=settings();limited.setProperty("guide-steps","");limited.setProperty("report-regions","capital");limited.setProperty("report-routes","");limited.setProperty("report-facilities","");limited.setProperty("report-events","");var v=view(limited,"iron_ore");assertEquals(1,v.nodes().size());assertFalse(v.toString().contains("광산 시험 상인"));assertFalse(v.toString().contains("ore_road"));assertFalse(v.toString().contains("mine_ore"));}
    @Test void hiddenGoodIsRejectedAndNotInGoodsSelection(){var limited=settings();limited.setProperty("guide-steps","");limited.setProperty("report-goods","iron_ingot");limited.setProperty("report-routes","");limited.setProperty("report-facilities","");assertThrows(IllegalArgumentException.class,()->view(limited,"iron_ore"));assertEquals(List.of(new EconomySupply.Good("iron_ingot","철괴")),view(limited,"iron_ingot").goods());}
    @Test void duplicateInvalidAndHiddenGuideReferencesFail(){for(var entry:Map.of("guide-steps","ore_market,ore_market","guide-step.ore_market.region","missing","guide-step.ore_market.reference","missing","guide-step.ore_transport.kind","MISSING","guide-step.capital_smelting.reference","mine_ore").entrySet()){var bad=settings();bad.setProperty(entry.getKey(),entry.getValue());assertThrows(RuntimeException.class,()->EconomySupply.parse(bad,c,definition));}var hidden=settings();hidden.setProperty("report-routes","");var d=EconomyReport.parse(hidden,c,merchants.first().shop());assertThrows(IllegalArgumentException.class,()->EconomySupply.parse(hidden,c,d));}
    @Test void publishedMerchantLocationsDoNotAllowRemoteTrade(){var v=view(p,"iron_ore");var city=v.nodes().stream().filter(n->n.section()==EconomySupply.Section.MARKET&&n.region().equals("capital")).findFirst().orElseThrow();var mine=v.nodes().stream().filter(n->n.section()==EconomySupply.Section.MARKET&&n.region().equals("mine")).findFirst().orElseThrow();assertTrue(EconomySupply.localTrade(city,merchants.get("capital_trader")));assertFalse(EconomySupply.localTrade(mine,merchants.get("capital_trader")));assertTrue(EconomySupply.localTrade(mine,merchants.get("mine_trader")));assertTrue(mine.lines().stream().anyMatch(s->s.contains("광산 시험 상인")&&s.contains("12.5")));}
    @Test void flowEventsAndTransitAreActualSnapshotValues(){var s=EconomyEngine.initial(c);for(int i=0;i<4;i++)s=EconomyEngine.advance(UUID.randomUUID(),c,s).state();var step=EconomyEngine.advance(UUID.randomUUID(),c,new EconomyEngine.State(s.tick(),s.markets(),s.shipments(),List.of(new EconomyEngine.Active(UUID.randomUUID(),"road_block",5,17))));var v=EconomySupply.project(c,definition,merchants,EconomySupply.parse(p,c,definition),step.state(),step.flows(),"iron_ore");assertEquals(5,v.tick());var route=v.nodes().stream().filter(n->n.section()==EconomySupply.Section.ROUTE).findFirst().orElseThrow();assertTrue(route.lines().stream().anyMatch(x->x.contains("차단")));assertFalse(route.lines().stream().anyMatch(x->x.contains("도착 예정 물량 없음")));assertEquals(4,EconomySupply.flowLines(step.flows().values().iterator().next()).size());}
    @Test void dtoIsImmutableAndHasNoOwnerOrPhysicalIdentity(){var v=view(p,"iron_ore");assertThrows(UnsupportedOperationException.class,()->v.nodes().clear());assertThrows(UnsupportedOperationException.class,()->v.nodes().getFirst().lines().clear());assertThrows(UnsupportedOperationException.class,()->v.steps().clear());assertFalse(v.toString().contains("player_uuid"));assertFalse(v.toString().contains("payload"));assertFalse(v.toString().contains("story_run_id"));}
    @Test void paginationHandlesLargeSupplyAndGuideBounds(){var many=new ArrayList<String>();for(int i=0;i<91;i++)many.add("노드 "+i);assertEquals(45,EconomyReport.page(many,0).size());assertEquals(1,EconomyReport.page(many,2).size());assertThrows(IllegalArgumentException.class,()->EconomyReport.page(many,3));var bad=settings();bad.setProperty("guide-step.ore_market.title","");assertThrows(RuntimeException.class,()->EconomySupply.parse(bad,c,definition));}
}
